-- =========================================================================
-- REASONCHAIN — REPLACE DEMO DATASET WITH FIREBASE COMPANY RELATIONSHIPS
-- Target Database: PostgreSQL 14+ (with JSONB, Indexes and ON CONFLICT upsert)
-- =========================================================================

BEGIN;

-- 1. ENSURE SCHEMA TABLES EXIST
CREATE TABLE IF NOT EXISTS import_batches (
    batch_id VARCHAR(100) PRIMARY KEY,
    source_system VARCHAR(100) NOT NULL,
    source_path VARCHAR(255) NOT NULL,
    schema_version VARCHAR(50),
    content_hash VARCHAR(128) NOT NULL,
    imported_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    record_counts JSONB,
    is_synthetic BOOLEAN DEFAULT TRUE,
    is_authoritative BOOLEAN DEFAULT FALSE,
    status VARCHAR(50) DEFAULT 'COMPLETED',
    metadata JSONB
);

CREATE TABLE IF NOT EXISTS company_links (
    company_key VARCHAR(100) PRIMARY KEY,
    cin VARCHAR(100),
    company_name VARCHAR(255) NOT NULL,
    source_path VARCHAR(255),
    mock_relationships_present BOOLEAN DEFAULT TRUE,
    canonical_id VARCHAR(100),
    resolution_status VARCHAR(50) DEFAULT 'RESOLVED',
    resolved_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    raw_payload JSONB
);

CREATE TABLE IF NOT EXISTS external_companies (
    id VARCHAR(100) PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    country VARCHAR(100),
    status VARCHAR(50) DEFAULT 'Active',
    is_synthetic BOOLEAN DEFAULT TRUE,
    raw_payload JSONB
);

CREATE TABLE IF NOT EXISTS relationship_claims (
    relationship_id VARCHAR(100) PRIMARY KEY,
    import_batch_id VARCHAR(100),
    relationship_type VARCHAR(100) NOT NULL,
    from_entity_id VARCHAR(100) NOT NULL,
    from_entity_type VARCHAR(100) NOT NULL,
    to_entity_id VARCHAR(100) NOT NULL,
    to_entity_type VARCHAR(100) NOT NULL,
    from_cin VARCHAR(100),
    to_cin VARCHAR(100),
    from_source_key VARCHAR(100),
    to_source_key VARCHAR(100),
    role VARCHAR(100),
    ownership_percentage NUMERIC(5,2),
    affiliation_reason TEXT,
    reason TEXT,
    contract_id VARCHAR(100),
    valid_from VARCHAR(50),
    valid_to VARCHAR(50),
    active BOOLEAN DEFAULT TRUE,
    confidence NUMERIC(3,2) DEFAULT 0.90,
    is_synthetic BOOLEAN DEFAULT TRUE,
    validation_status VARCHAR(50) DEFAULT 'VALIDATED',
    raw_payload JSONB
);
CREATE INDEX IF NOT EXISTS idx_rel_claims_from ON relationship_claims(from_entity_id);
CREATE INDEX IF NOT EXISTS idx_rel_claims_to ON relationship_claims(to_entity_id);
CREATE INDEX IF NOT EXISTS idx_rel_claims_type ON relationship_claims(relationship_type);

ALTER TABLE companies ADD COLUMN IF NOT EXISTS raw_payload JSONB;
ALTER TABLE companies ADD COLUMN IF NOT EXISTS is_synthetic BOOLEAN DEFAULT FALSE;
ALTER TABLE suppliers ADD COLUMN IF NOT EXISTS raw_payload JSONB;
ALTER TABLE suppliers ADD COLUMN IF NOT EXISTS is_synthetic BOOLEAN DEFAULT TRUE;
ALTER TABLE people ADD COLUMN IF NOT EXISTS raw_payload JSONB;
ALTER TABLE people ADD COLUMN IF NOT EXISTS is_synthetic BOOLEAN DEFAULT TRUE;
ALTER TABLE contracts ADD COLUMN IF NOT EXISTS raw_payload JSONB;
ALTER TABLE contracts ADD COLUMN IF NOT EXISTS is_synthetic BOOLEAN DEFAULT TRUE;
ALTER TABLE sanctions ADD COLUMN IF NOT EXISTS raw_payload JSONB;
ALTER TABLE sanctions ADD COLUMN IF NOT EXISTS list_name VARCHAR(255);
ALTER TABLE sanctions ADD COLUMN IF NOT EXISTS jurisdiction VARCHAR(100);
ALTER TABLE sanctions ADD COLUMN IF NOT EXISTS is_synthetic BOOLEAN DEFAULT TRUE;

-- 2. SAFE FOREIGN-KEY ORDER DELETION OF PREVIOUS BUSINESS DATASET
DELETE FROM company_directors;
DELETE FROM supplier_relationships;
DELETE FROM ownership;
DELETE FROM contracts;
DELETE FROM sanctions;
DELETE FROM relationship_claims;
DELETE FROM external_companies;
DELETE FROM company_links;
DELETE FROM companies;
DELETE FROM suppliers;
DELETE FROM people;

-- 3. INSERT RESOLVED ENTITIES AND RELATIONSHIPS

INSERT INTO import_batches (batch_id, source_system, source_path, schema_version, content_hash, record_counts, is_synthetic, is_authoritative, status, metadata) VALUES ('BATCH-20261013052330-09044968', 'Firebase Realtime Database', '/company_relationships', '1.0', '0904496870bd0473e7f4ea53b87f84607f9e4c23752c439aec01d460fc8cd522', '{"company_links_resolved": 10, "company_links_unresolved": 0, "companies_created": 10, "external_companies": 2, "people": 6, "suppliers": 5, "contracts": 5, "sanctions": 2, "relationships": 20}'::jsonb, TRUE, FALSE, 'COMPLETED', '{"authoritative": false, "company_targets_are_real_source_records": true, "data_origin": "synthetic_test_data", "purpose": "ReasonChain Knowledge Graph development and multi-hop reasoning tests", "schema_version": "1.0", "warning": "All entities and relationships in this branch are mock/synthetic. They must not be interpreted as real-world claims."}'::jsonb) ON CONFLICT (batch_id) DO NOTHING;

